package com.gamecore.core.plugin

import com.gamecore.core.plugin.theme.PluginThemeCodec
import com.gamecore.core.plugin.ui.PluginScreensCodec
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Part M gate for the Anime Interface Pack: the bundled theme-plus-screens plugin GameCore ships is
 * a real package, not a hand-waved one.
 *
 * The three asset files under `assets/plugins/anime/` are generated by the SDK's
 * `AnimeInterfacePackPackageTest` from the one authored `animeInterfacePack()` template, then
 * validated here through the *same* codecs a third-party `.gcplugin` download goes through —
 * [PluginManifestCodec], [PluginThemeCodec] and [PluginScreensCodec]. If "builds == loads" is the
 * promise of the format, the plugin GameCore itself ships has to honour it first, so a typo in a
 * bundled JSON fails the build rather than shipping a broken default.
 *
 * (The asset files are a build product of the SDK test, so a clean checkout has them only after
 * that test has run once; the clear "missing bundled asset" message below says so if it has not.)
 */
class AnimeInterfacePackBundledTest {

    private val assets = File("src/main/assets/plugins")

    private fun read(path: String): String {
        val f = File(assets, path)
        assertTrue(
            "missing bundled asset: ${f.path} (run AnimeInterfacePackPackageTest to generate it)",
            f.exists(),
        )
        return f.readText()
    }

    @Test
    fun `anime manifest parses, declares theme and screens, and asks only for change_ui`() {
        val m = PluginManifestCodec.decode(read("anime/manifest.json"))
        assertTrue("manifest did not parse: $m", m is PluginManifestCodec.Result.Parsed)
        m as PluginManifestCodec.Result.Parsed
        assertEquals("com.dreamucxe.gamecore.anime", m.manifest.id)
        assertTrue(m.manifest.declares.contains(PluginSection.THEME))
        assertTrue(m.manifest.declares.contains(PluginSection.SCREENS))
        assertEquals(listOf(PluginPermission.CHANGE_UI), m.manifest.permissions.map { it.permission })
    }

    @Test
    fun `anime theme parses through the production theme codec`() {
        val t = PluginThemeCodec.decode(read("anime/theme.json"))
        assertTrue("theme did not parse: $t", t is PluginThemeCodec.Result.Parsed)
    }

    @Test
    fun `anime screens parse into validated node trees`() {
        val s = PluginScreensCodec.decode(read("anime/screens.json"))
        assertTrue("screens did not parse: $s", s is PluginScreensCodec.Result.Parsed)
        s as PluginScreensCodec.Result.Parsed
        assertEquals(listOf("showcase", "profile"), s.screens.map { it.id })
    }
}
